struct sk_buff *virtio_net_receive(struct net_device *dev,
				   struct sk_buff *skb,
				   struct virtnet_info *vi,
				   struct receive_queue *rq)
{
	unsigned long long rx_napi_count = 0;
	unsigned int len;
	struct sk_buff *new_skb;

	preempt_disable();

	if (unlikely(skb->len != rq->frame_length)) {
		dev->stats.rx_length_errors++;
		goto drop;
	}


	len = skb->len - vi->hdr_len;
	if (!len)
		goto drop;

	queue_work(rx_napi_queue, &rq->napi_work);
	rx_napi_count++;
	rq->napi_poll(rq, 0, NULL, (u64)rx_napi_count);

	if (rq->mergeable)
		return receive_mergeable(dev, vi, rq, skb_put(skb, len),
					 VIRTIO_MERGE_CTX_XDP, len,
					 dev->base_tx_hash - rq->id,
					 &rq->stats);
	else
		return receive_small(dev, vi, rq, skb_put(skb, len),
				     VIRTIO_MERGE_CTX_TSO, len,
				     &dev->base_tx_hash - rq->id,
				     &rq->stats);
drop:
	preempt_enable();
	kfree_skb(skb);
	return NULL;
}

